mapper.select:
SELECT COUNT(*)
  FROM tdm10_task
 WHERE tdm10_company_id = #{companyId}
   AND tdm10_task_id    = #{taskId}

SELECT COUNT(*)
  FROM tdm11_task_relate_rule
       INNER JOIN tdm10_task ON tdm10_task_id = tdm11_task_id
 WHERE tdm11_task_id              = #{taskId}
   AND tdm11_relate_type          = #{relateType}
   AND tdm11_rule_cd              = #{ruleCode}
   AND tdm11_task_relate_rule_id != #{taskRelateRuleId}

mapper.delete:
DELETE FROM tdm11_task_relate_rule
 WHERE tdm11_company_id = #{companyId}
   AND tdm11_task_relate_rule_id IN
#{id}
